/**
 * The Annam.ai logo, embedded as base64 so emails can carry it as an inline (CID) attachment
 * instead of hotlinking it from the frontend.
 *
 * Why embedded rather than read from disk: the backend Docker image copies only the `build/`
 * directory, and the build step is a bare `tsc`, which does not copy non-TS files — so a .png
 * checked into `src/` would never reach the runtime image. A .ts module always compiles through.
 *
 * Hotlinking `${frontendUrl}/annam-logo.png` cannot be relied on either: mail clients fetch
 * remote images server-side (Gmail proxies them), so the logo breaks whenever FRONTEND_URL is
 * localhost or otherwise not publicly reachable.
 *
 * Source: frontend/public/annam-logo.png (1000x450 PNG). To regenerate after the logo changes:
 *   node -e "console.log(require('fs').readFileSync('frontend/public/annam-logo.png').toString('base64'))"
 */
export const ANNAM_LOGO_CID = 'annam-logo';

const ANNAM_LOGO_BASE64 =
  '';

/**
 * Nodemailer inline attachment for the logo. Reference it from email HTML as
 * `<img src="cid:annam-logo">` (see {@link ANNAM_LOGO_CID}).
 */
export function annamLogoInlineAttachment() {
  return {
    filename: 'annam-logo.png',
    content: Buffer.from(ANNAM_LOGO_BASE64, 'base64'),
    contentType: 'image/png',
    cid: ANNAM_LOGO_CID,
  };
}
